namespace sv_f170aeff895d454f93fae9151ae887d0.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_f170aeff895d454f93fae9151ae887d0.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(ActiveSection == section.Key ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                <span class="nav-icon">@section.Icon</span>
                <span class="nav-label">@section.Label</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionChanged { get; set; }

    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

@namespace sv_f170aeff895d454f93fae9151ae887d0.Components.Pages.Settings
@using sv_f170aeff895d454f93fae9151ae887d0.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Profile Settings</h2>

    @if (isLoading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="avatar-preview">
            <img src="@avatarUrl" alt="Avatar preview" class="avatar-image" />
            <p class="avatar-url">@avatarUrl</p>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="displayName" @bind:event="oninput" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="email" @bind:event="oninput" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" rows="4" @bind="bio" @bind:event="oninput"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-secondary" @onclick="DiscardChanges" disabled="@isSaving">
                Discard Changes
            </button>
        </div>

        @if (!string.IsNullOrEmpty(successMessage))
        {
            <div class="toast toast-success">@successMessage</div>
        }
    }
</section>

@code {
    private string displayName = "";
    private string email = "";
    private string avatarUrl = "";
    private string bio = "";
    private bool isLoading = true;
    private bool isSaving;
    private string successMessage = "";

    private UserProfile? savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(savedProfile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        displayName = profile.DisplayName;
        email = profile.Email;
        avatarUrl = profile.AvatarUrl;
        bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        successMessage = "";
        var profile = new UserProfile(displayName, email, avatarUrl, bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        isSaving = false;
        successMessage = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
        successMessage = "";
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = "";
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_f170aeff895d454f93fae9151ae887d0.Components.Pages.Settings
@using sv_f170aeff895d454f93fae9151ae887d0.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Notification Preferences</h2>

    @if (isLoading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="emailNotifications" />
                <span class="toggle-label">Email Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="pushNotifications" />
                <span class="toggle-label">Push Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="weeklyDigest" />
                <span class="toggle-label">Weekly Digest</span>
            </label>
        </div>

        <div class="muted-channels">
            <h3>Muted Channels</h3>
            @if (channels.Count == 0)
            {
                <p class="empty-state">No channels available.</p>
            }
            else
            {
                <ul class="channel-list">
                    @foreach (var channel in channels)
                    {
                        <li class="channel-item">
                            <label>
                                <input type="checkbox"
                                       checked="@IsChannelMuted(channel)"
                                       @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
                        </li>
                    }
                </ul>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (!string.IsNullOrEmpty(successMessage))
        {
            <div class="toast toast-success">@successMessage</div>
        }
    }
</section>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<string> mutedChannels = new();
    private List<string> channels = new();
    private bool isLoading = true;
    private bool isSaving;
    private string successMessage = "";

    /// <summary>
    /// All available channels — in production this would come from an API.
    /// </summary>
    private static readonly List<string> AllChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new List<string>(prefs.MutedChannels);
        channels = AllChannels;
        isLoading = false;
    }

    private bool IsChannelMuted(string channel) => mutedChannels.Contains(channel);

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!muted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        successMessage = "";
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        isSaving = false;
        successMessage = "Preferences saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = "";
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_f170aeff895d454f93fae9151ae887d0.Components.Pages.Settings
@using sv_f170aeff895d454f93fae9151ae887d0.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Security Settings</h2>

    @if (isLoading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="TogglePasswordPanel">
                <span>Change Password</span>
                <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
            </button>

            @if (showPasswordPanel)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>

                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="error-message">@passwordError</div>
                    }
                    @if (!string.IsNullOrEmpty(passwordSuccess))
                    {
                        <div class="toast toast-success">@passwordSuccess</div>
                    }

                    <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@isChangingPassword">
                        @(isChangingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="security-item">
            <h3>Two-Factor Authentication</h3>
            <div class="twofa-status">
                <span class="status-indicator @(twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
                <label class="toggle-item">
                    <input type="checkbox" @bind="twoFactorEnabled" />
                    <span class="toggle-label">Enable 2FA</span>
                </label>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="security-item">
            <h3>Active Sessions</h3>
            @if (sessions.Count == 0)
            {
                <p class="empty-state">No active sessions.</p>
            }
            else
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session.Id != currentSessionId)
                                    {
                                        <button class="btn btn-danger btn-sm"
                                                @onclick="() => ConfirmRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-session-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay" @onclick="CancelRevoke">
                <div class="dialog" @onclick:stopPropagation="true">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="dialog-actions">
                        <button class="btn btn-danger" @onclick="RevokeSessionAsync" disabled="@isRevoking">
                            @(isRevoking ? "Revoking..." : "Yes, Revoke")
                        </button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke" disabled="@isRevoking">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</section>

@code {
    private bool isLoading = true;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private string passwordSuccess = "";
