@namespace sv_f170aeff895d454f93fae9151ae887d0.Components.Pages.Settings
@using sv_f170aeff895d454f93fae9151ae887d0.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Notification Preferences</h2>

    @if (isLoading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="emailNotifications" />
                <span class="toggle-label">Email Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="pushNotifications" />
                <span class="toggle-label">Push Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="weeklyDigest" />
                <span class="toggle-label">Weekly Digest</span>
            </label>
        </div>

        <div class="muted-channels">
            <h3>Muted Channels</h3>
            @if (channels.Count == 0)
            {
                <p class="empty-state">No channels available.</p>
            }
            else
            {
                <ul class="channel-list">
                    @foreach (var channel in channels)
                    {
                        <li class="channel-item">
                            <label>
                                <input type="checkbox"
                                       checked="@IsChannelMuted(channel)"
                                       @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
                        </li>
                    }
                </ul>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (!string.IsNullOrEmpty(successMessage))
        {
            <div class="toast toast-success">@successMessage</div>
        }
    }
</section>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<string> mutedChannels = new();
    private List<string> channels = new();
    private bool isLoading = true;
    private bool isSaving;
    private string successMessage = "";

    /// <summary>
    /// All available channels — in production this would come from an API.
    /// </summary>
    private static readonly List<string> AllChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new List<string>(prefs.MutedChannels);
        channels = AllChannels;
        isLoading = false;
    }

    private bool IsChannelMuted(string channel) => mutedChannels.Contains(channel);

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!muted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        successMessage = "";
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        isSaving = false;
        successMessage = "Preferences saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = "";
        await InvokeAsync(StateHasChanged);
    }
}

